SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS restaurant_reservation_settings (tenant_id VARCHAR(36) NOT NULL,reservations_enabled TINYINT(1) NOT NULL DEFAULT 1,waitlist_enabled TINYINT(1) NOT NULL DEFAULT 1,advance_days INT NOT NULL DEFAULT 7,reservation_grace_minutes INT NOT NULL DEFAULT 15,waiting_grace_minutes INT NOT NULL DEFAULT 5,waitlist_expiry_minutes INT NOT NULL DEFAULT 120,min_party_size INT NOT NULL DEFAULT 1,max_party_size INT NOT NULL DEFAULT 20,updated_at BIGINT NOT NULL,PRIMARY KEY(tenant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE restaurant_reservation_settings ADD COLUMN reservations_enabled TINYINT(1) NOT NULL DEFAULT 1;
ALTER TABLE restaurant_reservation_settings ADD COLUMN waitlist_enabled TINYINT(1) NOT NULL DEFAULT 1;
