ALTER TABLE restaurant_reservation_settings ADD COLUMN waiting_grace_minutes INT NOT NULL DEFAULT 5;
ALTER TABLE restaurant_reservation_settings ADD COLUMN waitlist_expiry_minutes INT NOT NULL DEFAULT 120;
ALTER TABLE restaurant_reservation_settings ADD COLUMN min_party_size INT NOT NULL DEFAULT 1;
ALTER TABLE restaurant_reservation_settings ADD COLUMN max_party_size INT NOT NULL DEFAULT 20;
