CREATE TABLE IF NOT EXISTS restaurant_table_runtime (tenant_id VARCHAR(36) NOT NULL,table_id VARCHAR(36) NOT NULL,qr_token VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'available',waiter_user_id VARCHAR(36) NULL,service_started_at BIGINT NULL,min_order DECIMAL(12,2) NULL,service_fee DECIMAL(12,2) NULL,service_fee_label_ar VARCHAR(160) NULL,service_fee_label_en VARCHAR(160) NULL,service_fee_label_fr VARCHAR(160) NULL,updated_at BIGINT NOT NULL,PRIMARY KEY(table_id),UNIQUE KEY restaurant_table_runtime_qr(qr_token),KEY restaurant_table_runtime_tenant_status(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE restaurant_table_runtime ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'available';
ALTER TABLE restaurant_table_runtime ADD COLUMN waiter_user_id VARCHAR(36) NULL;
